	t.Run("windows falls back to unresolved path on EvalSymlinks failure", func(t *testing.T) {
		t.Parallel()
		got, err := resolveHookExePath(exe, func(string) (string, error) {
			return "", junctionErr
		}, "windows")
		if err != nil {
